begin;
create unique index if not exists cash_sessions_one_open_per_register_idx on public.cash_sessions (tenant_id, branch_id, cash_register_id) where status = 'open';
do $$ declare t text; p text; begin foreach t in array array['cash_sessions','cash_movements','presales','inventory_stocks','inventory_movements'] loop foreach p in array array[t || '_select_member', t || '_insert_member', t || '_update_member', t || '_insert_admin', t || '_update_admin'] loop execute format('drop policy if exists %I on public.%I', p, t); end loop; end loop; end $$;
create policy cash_sessions_select_branch on public.cash_sessions for select to authenticated using (public.has_tenant_access(tenant_id) and public.has_active_branch_access(tenant_id, branch_id));
create policy cash_sessions_insert_branch on public.cash_sessions for insert to authenticated with check (public.has_tenant_access(tenant_id) and public.has_active_branch_access(tenant_id, branch_id));
create policy cash_sessions_update_branch on public.cash_sessions for update to authenticated using (public.has_tenant_access(tenant_id) and public.has_active_branch_access(tenant_id, branch_id)) with check (public.has_tenant_access(tenant_id) and public.has_active_branch_access(tenant_id, branch_id));
create policy cash_movements_select_branch on public.cash_movements for select to authenticated using (public.has_tenant_access(tenant_id) and exists (select 1 from public.cash_sessions s where s.id=cash_movements.cash_session_id and s.tenant_id=cash_movements.tenant_id and public.has_active_branch_access(s.tenant_id,s.branch_id)));
create policy cash_movements_insert_branch on public.cash_movements for insert to authenticated with check (public.has_tenant_access(tenant_id) and exists (select 1 from public.cash_sessions s where s.id=cash_movements.cash_session_id and s.tenant_id=cash_movements.tenant_id and public.has_active_branch_access(s.tenant_id,s.branch_id)));
create policy presales_select_branch on public.presales for select to authenticated using (public.has_tenant_access(tenant_id) and branch_id is not null and public.has_active_branch_access(tenant_id, branch_id));
create policy presales_insert_branch on public.presales for insert to authenticated with check (public.has_tenant_access(tenant_id) and branch_id is not null and public.has_active_branch_access(tenant_id, branch_id));
create policy presales_update_branch on public.presales for update to authenticated using (public.has_tenant_access(tenant_id) and branch_id is not null and public.has_active_branch_access(tenant_id, branch_id)) with check (public.has_tenant_access(tenant_id) and branch_id is not null and public.has_active_branch_access(tenant_id, branch_id));
create policy inventory_stocks_select_branch on public.inventory_stocks for select to authenticated using (public.has_tenant_access(tenant_id) and exists (select 1 from public.warehouses w where w.id=inventory_stocks.warehouse_id and w.tenant_id=inventory_stocks.tenant_id and public.has_active_branch_access(w.tenant_id,w.branch_id)));
create policy inventory_movements_select_branch on public.inventory_movements for select to authenticated using (public.has_tenant_access(tenant_id) and exists (select 1 from public.warehouses w where w.id=inventory_movements.warehouse_id and w.tenant_id=inventory_movements.tenant_id and public.has_active_branch_access(w.tenant_id,w.branch_id)));
revoke insert, update, delete on public.inventory_stocks, public.inventory_movements from authenticated;
commit;
